<template>
  <Modal v-if="modals.role && availableRoles.length" @close="close">
    <h3>
      Choose a new character for
      {{
        playerIndex >= 0 && players.length
        ? players[playerIndex].name
        : "bluffing"
      }}
    </h3>

    <!-- Edition roles -->
    <div v-if="tab === 'editionRoles' || !otherTravelers.size" class="roles-container">
      <button v-if="pagedRoles.length > 1" class="nav-button nav-left" @click="prevPage">
        ◀
      </button>

      <ul class="tokens">
        <li v-for="role in pagedRoles[currentPage]" :class="[role.team]" :key="role.id" @click="setRole(role)">
          <Token :role="role" />
        </li>
      </ul>

      <button v-if="pagedRoles.length > 1" class="nav-button nav-right" @click="nextPage">
        ▶
      </button>
    </div>

    <!-- Other travelers -->
    <ul class="tokens" v-if="tab === 'otherTravelers' && otherTravelers.size">
      <li v-for="role in otherTravelers.values()" :class="[role.team]" :key="role.id" @click="setRole(role)">
        <Token :role="role" />
      </li>
    </ul>

    <div class="button-group" v-if="playerIndex >= 0 && otherTravelers.size && !session.isSpectator">
      <span class="button" :class="{ townsfolk: tab === 'editionRoles' }" @click="tab = 'editionRoles'">Edition
        Roles</span>
      <span class="button" :class="{ townsfolk: tab === 'otherTravelers' }" @click="tab = 'otherTravelers'">Other
        Travelers</span>
    </div>
  </Modal>
</template>

<script>
import { mapMutations, mapState } from "vuex";
import Modal from "./Modal";
import Token from "../Token";

export default {
  components: { Token, Modal },
  props: ["playerIndex"],
  data() {
    return {
      tab: "editionRoles",
      currentPage: 0,
      rolesPerPage: 44,
    };
  },
  computed: {
    ...mapState(["modals", "roles", "session", "otherTravelers"]),
    ...mapState("players", ["players"]),

    availableRoles() {
      const availableRoles = [];
      const players = this.$store.state.players.players;
      this.$store.state.roles.forEach((role) => {
        // don't show bluff roles that are already assigned to players
        if (
          this.playerIndex >= 0 ||
          (this.playerIndex < 0 &&
            !players.some((player) => player.role.id === role.id))
        ) {
          availableRoles.push(role);
        }
      });
      availableRoles.push({});
      return availableRoles;
    },

    pagedRoles() {
      const chunks = [];
      for (let i = 0; i < this.availableRoles.length; i += this.rolesPerPage) {
        chunks.push(this.availableRoles.slice(i, i + this.rolesPerPage));
      }
      return chunks;
    },
  },
  methods: {
    ...mapMutations(["toggleModal"]),

    nextPage() {
      if (this.currentPage < this.pagedRoles.length - 1) this.currentPage++;
      else this.currentPage = 0;
    },
    prevPage() {
      if (this.currentPage > 0) this.currentPage--;
      else this.currentPage = this.pagedRoles.length - 1;
    },

    setRole(role) {
      if (this.playerIndex < 0) {
        this.$store.commit("players/setBluff", {
          index: this.playerIndex * -1 - 1,
          role
        });
      } else {
        if (this.session.isSpectator && role.team === "traveler") return;
        const player = this.$store.state.players.players[this.playerIndex];
        this.$store.commit("players/update", {
          player,
          property: "role",
          value: role
        });
      }
      this.tab = "editionRoles";
      this.$store.commit("toggleModal", "role");
    },
    close() {
      this.tab = "editionRoles";
      this.toggleModal("role");
    },
  },
  watch: {
    'modals.role'(isOpen) {
      if (isOpen) {
        this.currentPage = 0;
      }
    }
  }
};
</script>

