<template>
  <Modal v-if="modals.reminder && availableReminders.length && players[playerIndex]" @close="toggleModal('reminder')">
    <h3>Choose a reminder token:</h3>

    <div class="reminders-container">
      <!-- Page navigation buttons -->
      <button v-if="pagedReminders.length > 1" class="nav-button nav-left" @click="prevPage">
        ◀
      </button>

      <ul class="reminders">
        <li v-for="reminder in pagedReminders[currentPage]" class="reminder" :class="[reminder.role]"
          :key="reminder.role + ' ' + reminder.name" @click="addReminder(reminder)">
          <span class="icon" :style="{
            backgroundImage: `url(${reminder.image && grimoire.isImageOptIn
              ? reminder.image
              : require('../../assets/icons/' +
                (reminder.imageAlt || reminder.role) +
                '.png')
              })`
          }"></span>
          <span class="text">{{ reminder.name }}</span>
        </li>
      </ul>

      <button v-if="pagedReminders.length > 1" class="nav-button nav-right" @click="nextPage">
        ▶
      </button>
    </div>

    <!-- Show all toggle -->
    <div class="show-all-toggle">
      <label>
        <input type="checkbox" v-model="showAllReminders" />
        Show all reminders
      </label>
    </div>
  </Modal>
</template>

<script>
import Modal from "./Modal";
import { mapMutations, mapState } from "vuex";

const mapReminder = ({ id, image, imageAlt }) => (name) => ({
  role: id,
  image,
  imageAlt,
  name,
});

export default {
  components: { Modal },
  props: ["playerIndex"],
  data() {
    return {
      showAllReminders: false,
      currentPage: 0, // ✅ paging support
      remindersPerPage: 33,
    };
  },
  computed: {
    ...mapState(["modals", "grimoire"]),
    ...mapState("players", ["players"]),

    availableReminders() {
      let reminders = [];
      const { players, bluffs } = this.$store.state.players;

      this.$store.state.roles.forEach((role) => {
        // add reminders from player roles
        if (players.some((p) => p.role.id === role.id)) {
          reminders = [...reminders, ...role.reminders.map(mapReminder(role))];
        }
        // add reminders from bluff roles
        else if (bluffs.some((bluff) => bluff.id === role.id)) {
          reminders = [...reminders, ...role.reminders.map(mapReminder(role))];
        }
        // add global reminders
        if (role.remindersGlobal && role.remindersGlobal.length) {
          reminders = [
            ...reminders,
            ...role.remindersGlobal.map(mapReminder(role)),
          ];
        }
      });

      // add fabled reminders
      this.$store.state.players.fabled.forEach((role) => {
        reminders = [...reminders, ...role.reminders.map(mapReminder(role))];
      });

      // add out of script traveler reminders
      this.$store.state.otherTravelers.forEach((role) => {
        if (players.some((p) => p.role.id === role.id)) {
          reminders = [...reminders, ...role.reminders.map(mapReminder(role))];
        }
      });

      reminders.push({ role: "good", name: "Good" });
      reminders.push({ role: "evil", name: "Evil" });
      reminders.push({ role: "minion", name: "Minion" });
      reminders.push({ role: "evil", name: "Demon" });
      reminders.push({ role: "custom", name: "Custom note" });
      return reminders;
    },

    // ✅ all possible reminders
    allReminders() {
      let reminders = [];
      this.$store.state.roles.forEach((role) => {
        if (role.reminders?.length) {
          reminders = [...reminders, ...role.reminders.map(mapReminder(role))];
        }
        if (role.remindersGlobal?.length) {
          reminders = [
            ...reminders,
            ...role.remindersGlobal.map(mapReminder(role)),
          ];
        }
      });
      reminders.push({ role: "good", name: "Good" });
      reminders.push({ role: "evil", name: "Evil" });
      reminders.push({ role: "minion", name: "Minion" });
      reminders.push({ role: "evil", name: "Demon" });
      reminders.push({ role: "custom", name: "Custom note" });
      return reminders;
    },

    filteredReminders() {
      return this.showAllReminders ? this.allReminders : this.availableReminders;
    },

    // ✅ split into pages
    pagedReminders() {
      const chunks = [];
      for (let i = 0; i < this.filteredReminders.length; i += this.remindersPerPage) {
        chunks.push(this.filteredReminders.slice(i, i + this.remindersPerPage));
      }
      return chunks;
    },
  },

  methods: {
    ...mapMutations(["toggleModal"]),

    addReminder(reminder) {
      const player = this.$store.state.players.players[this.playerIndex];
      let value;
      if (reminder.role === "custom") {
        const name = prompt("Add a custom reminder note");
        if (!name) return;
        value = [...player.reminders, { role: "custom", name }];
      } else {
        value = [...player.reminders, reminder];
      }
      this.$store.commit("players/update", {
        player,
        property: "reminders",
        value,
      });
      this.$store.commit("toggleModal", "reminder");
    },

    nextPage() {
      if (this.currentPage < this.pagedReminders.length - 1) this.currentPage++;
      else this.currentPage = 0;
    },
    prevPage() {
      if (this.currentPage > 0) this.currentPage--;
      else this.currentPage = this.pagedReminders.length - 1;
    },
  },

  // ✅ Reset checkbox and page when modal opens
  watch: {
    "modals.reminder"(isOpen) {
      if (isOpen) {
        this.showAllReminders = false;
        this.currentPage = 0;
      }
    },

    showAllReminders(newValue) {
      if (!newValue) {
        this.currentPage = 0;
      }
    },
  },
};
</script>

